begin;
do $$
declare u uuid:='00000000-0000-0000-0000-0000000000b5'; outro uuid:='00000000-0000-0000-0000-0000000000b6'; chave uuid:=gen_random_uuid(); criacao uuid:=gen_random_uuid(); r jsonb; ids uuid[]; tx uuid; pulada uuid; conta uuid; linha uuid;
begin
 insert into auth.users(id) values(u),(outro);
 perform set_config('request.jwt.claims',jsonb_build_object('sub',u)::text,true);
 perform public.criar_receitas_previstas(criacao,'Salário teste','TRANSFERENCIA','2024-02-01','[{"dia":15,"valor":10000},{"dia":30,"valor":20000}]',null);
 perform public.criar_receitas_previstas(criacao,'Salário teste','TRANSFERENCIA','2024-02-01','[{"dia":15,"valor":10000},{"dia":30,"valor":20000}]',null);
 if (select count(*) from public.recorrencias where user_id=u)<>2 then raise exception 'cadastro repetido duplicou';end if;
 r:=public.consultar_receitas_previstas('2024-02-01');
 select array_agg(id order by id) into ids from public.ocorrencias_receita where user_id=u;
 if cardinality(ids)<>2 or not exists(select 1 from public.ocorrencias_receita where user_id=u and data_prevista='2024-02-29') then raise exception 'calendário';end if;
 perform public.aplicar_recorrencias();
 if exists(select 1 from public.transacoes_origem where user_id=u) then raise exception 'previsão virou caixa';end if;
 r:=public.confirmar_receitas_previstas(chave,ids,'2024-01-25',30000,'Férias');tx:=(r->>'transacao_id')::uuid;
 r:=public.confirmar_receitas_previstas(chave,ids,'2024-01-25',30000,'Férias');
 if (r->>'transacao_id')::uuid<>tx or (select saldo_caixa from public.vw_carteira)<>30000 then raise exception 'duplicou recebimento';end if;
 if (select count(*) from public.ocorrencias_receita where transacao_id=tx and status='RECEBIDA')<>2 then raise exception 'conjunto não resolvido';end if;
 begin perform public.excluir_transacao(tx);raise exception 'exclusão genérica perdeu agenda';exception when sqlstate 'FW409' then null;end;
 begin perform public.confirmar_receitas_previstas(chave,ids,'2024-01-25',40000,'Férias');raise exception 'conflito aceito';exception when sqlstate 'FW409' then null;end;
 conta:=(public.criar_conta_bancaria('Conta sintética férias',0,'2024-01-01')->>'id')::uuid;
 perform public.importar_extrato_conta(conta,'CSV','[{"data":"2024-01-25","valor":30000,"descricao":"Salário férias"}]');
 select id into linha from public.linhas_extrato_conta where conta_id=conta;
 perform public.conciliar_linha_conta(linha,'VINCULAR',tx,null,null);
 perform public.fechar_conciliacao_conta(conta,'2024-01-25',30000);
 begin perform public.desfazer_receita_prevista(tx);raise exception 'desfez recebimento conciliado';exception when sqlstate 'FW409' then null;end;
 if exists(select 1 from public.confirmacoes_receita where transacao_id=tx and desfeita) or (select count(*) from public.ocorrencias_receita where transacao_id=tx)<>2 then raise exception 'falha de desfazer alterou grupo';end if;
 begin perform public.desfazer_conciliacao_conta(linha);raise exception 'desfez período fechado';exception when sqlstate 'FW409' then null;end;
 perform public.reabrir_conciliacao_conta(conta,'Conferência sintética de férias');
 perform public.desfazer_conciliacao_conta(linha);
 perform public.desfazer_receita_prevista(tx);perform public.desfazer_receita_prevista(tx);
 if (select saldo_caixa from public.vw_carteira)<>0 or exists(select 1 from public.ocorrencias_receita where user_id=u and status<>'PREVISTA') then raise exception 'desfazer parcial';end if;
 perform public.marcar_receita_nao_recebida(ids[1],true,'Já recebi antes');perform public.marcar_receita_nao_recebida(ids[1],true,'Já recebi antes');
 if (select status from public.ocorrencias_receita where id=ids[1])<>'PULADA' then raise exception 'pulo';end if;
 perform public.consultar_receitas_previstas('2024-03-01');
 if not exists(select 1 from public.ocorrencias_receita where user_id=u and data_prevista='2024-03-30' and status='PREVISTA') then raise exception 'cancelou mês futuro';end if;
 perform public.marcar_receita_nao_recebida(ids[1],false,null);
 if (select status from public.ocorrencias_receita where id=ids[1])<>'PREVISTA' then raise exception 'desfazer pulo';end if;
 perform public.criar_receitas_previstas(gen_random_uuid(),'Início depois do dia','PIX','2024-02-20','[{"dia":15,"valor":1000}]',null);
 select id into pulada from public.recorrencias where user_id=u and descricao='Início depois do dia';
 perform public.editar_recorrencia(pulada,'Início preservado',1000,'RECEITA','PIX',15,null);
 if (select proxima_data from public.recorrencias where id=pulada)<>'2024-02-20' then raise exception 'edição perdeu início';end if;
 perform public.alternar_recorrencia(pulada,false);perform public.alternar_recorrencia(pulada,true);
 if (select proxima_data from public.recorrencias where id=pulada)<>'2024-02-20' then raise exception 'reativação perdeu início';end if;
 perform public.consultar_receitas_previstas('2024-02-01');
 if exists(select 1 from public.ocorrencias_receita where recorrencia_id=pulada and competencia='2024-02-01') then raise exception 'previsão anterior ao início';end if;
 perform public.consultar_receitas_previstas('2024-04-01');
 if not exists(select 1 from public.ocorrencias_receita where recorrencia_id=pulada and competencia='2024-04-01') then raise exception 'perdeu pendência histórica';end if;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outro)::text,true);
 begin perform public.marcar_receita_nao_recebida(ids[1],true,null);raise exception 'pulo cruzado';exception when sqlstate 'FW404' then null;end;
 begin perform public.confirmar_receitas_previstas(gen_random_uuid(),ids,'2024-01-25',30000,null);raise exception 'confirmação cruzada';exception when sqlstate 'FW404' then null;end;
 if has_function_privilege('anon','public.confirmar_receitas_previstas(uuid,uuid[],date,bigint,text)','execute') then raise exception 'anon autorizado';end if;
 raise notice 'OK: todos os asserts de calendário, previsão, antecipação, pulo, desfazer, repetição e isolamento';
end $$;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-0000000000b6"}',true);
do $$ begin if exists(select 1 from public.ocorrencias_receita) or exists(select 1 from public.confirmacoes_receita) then raise exception 'RLS';end if;end $$;
rollback;
